WITH exploded AS (SELECT id, service, host, log_ts, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS k, value) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, MIN(status_code) AS min_status_code, SUM(CASE WHEN host = 'h2' THEN status_code ELSE 0 END) AS h2_status_code, SORT_ARRAY(COLLECT_SET(service)) AS service_list, COUNT(CASE WHEN host = 'h3' THEN 1 END) AS h3_count, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, GROUPING(DATE_TRUNC('DAY', log_ts)) AS grouping_id FROM exploded GROUP BY CUBE (DATE_TRUNC('DAY', log_ts)) HAVING min_status_code > 0;
